set -euo pipefail
cd /opt/news-flow/current
/opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {DatabaseSync} from 'node:sqlite';import {createRequire} from 'node:module';import {createHash} from 'node:crypto';
const root='/var/lib/news-flow/live-priority-20261123',db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),require=createRequire('/opt/news-flow/current/package.json'),env=require('dotenv').parse(fs.readFileSync('/etc/news-flow/news.env')),ES=require('elasticsearch'),es=new ES.Client({host:env.ES5_HOST,apiVersion:'5.6',log:[],maxRetries:0,requestTimeout:20000}),start=JSON.parse(db.prepare("SELECT value FROM flow_meta WHERE key='live_priority_deployed_20261123'").get().value).at,rows=db.prepare("SELECT es_index,es_type,es_id,url,status FROM import_receipts WHERE imported_at>=? AND es_index='master202648'").all(start),report={at:new Date().toISOString(),since:new Date(start).toISOString(),receipts:rows.length,found:0,createdToday:0,existingToday:0,publishedLastHour:0,createdPublishedLastHour:0,existingPublishedLastHour:0,examples:[],failed:[]};
try{
 const info=await es.info(),proof=JSON.parse(fs.readFileSync('/etc/news-flow/identity-proof.json')).summary;if(!proof.verified||!info.version.number.startsWith('5.6.')||createHash('sha256').update(info.cluster_uuid).digest('hex')!==proof.clusterFingerprint)throw Error('ES_IDENTITY_CHANGED');
 for(let i=0;i<rows.length;i+=500){const group=rows.slice(i,i+500),r=await es.mget({body:{docs:group.map(a=>({_index:a.es_index,_type:a.es_type,_id:a.es_id,_source:['url','title','publishedDate']}))}});for(let n=0;n<group.length;n++){const row=group[n],hit=r.docs[n],s=hit?._source;if(hit?.found&&s.url===row.url&&typeof s.title==='string'&&Date.parse(s.publishedDate)){report.found++;const pub=Date.parse(s.publishedDate);if(new Date(pub+7*3600000).toISOString().slice(0,10)==='2026-11-23')report[row.status==='created'?'createdToday':'existingToday']++;if(pub>=Date.now()-3600000&&pub<=Date.now()+60000){report.publishedLastHour++;report[row.status==='created'?'createdPublishedLastHour':'existingPublishedLastHour']++;if(report.examples.length<8)report.examples.push({url:s.url,title:s.title,publishedDate:s.publishedDate,receiptStatus:row.status});}}else report.failed.push({index:row.es_index,id:row.es_id,found:!!hit?.found});}}
 const target=await es.get({index:'master202647',type:'newsTopic',id:'c65acc43c0aadfd45a358347f3e132f4'});report.originalMiss={found:target.found,url:target._source?.url,title:target._source?.title,bodyLength:target._source?.content?.length,publishedDate:target._source?.publishedDate};report.verified=report.found===report.receipts&&report.receipts>0&&report.originalMiss.found;
 fs.writeFileSync(root+'/es-live-readback.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report));
}catch(e){console.log(JSON.stringify({verified:false,error:/^[A-Z0-9_]+$/.test(e.message||'')?e.message:'ES_LIVE_READBACK_FAILED'}));process.exitCode=1;}finally{db.close();es.close();}
NODE
